        $entity->setOffPeakStart($offPeak['window_start'] ?? null);
        $entity->setOffPeakEnd($offPeak['window_end'] ?? null);
        $entity->setOffPeakMultiplier((string)($offPeak['multiplier'] ?? '1'));
