CREATE TABLE usage_events (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, provider_code VARCHAR(64) NOT NULL, provider_request_id VARCHAR(128) NOT NULL, model_code VARCHAR(64) NOT NULL, user_id VARCHAR(128) NOT NULL, ts TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, tokens_input BIGINT NOT NULL, tokens_output BIGINT NOT NULL, tokens_cache_read BIGINT NOT NULL, tokens_cache_write BIGINT NOT NULL, cost NUMERIC(20, 6) DEFAULT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX uniq_usage_provider_request ON usage_events (provider_code, provider_request_id);
CREATE TABLE prices (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, provider_code VARCHAR(64) NOT NULL, model_code VARCHAR(64) NOT NULL, valid_from TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL, currency VARCHAR(8) NOT NULL, unit VARCHAR(32) NOT NULL, input_rate NUMERIC(20, 6) DEFAULT NULL, output_rate NUMERIC(20, 6) DEFAULT NULL, cache_read_rate NUMERIC(20, 6) DEFAULT NULL, cache_write_rate NUMERIC(20, 6) DEFAULT NULL, any_rate NUMERIC(20, 6) DEFAULT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX uniq_price_provider_model_valid ON prices (provider_code, model_code, valid_from);
CREATE TABLE models (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, provider_code VARCHAR(64) NOT NULL, code VARCHAR(64) NOT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX uniq_model_provider_code ON models (provider_code, code);
CREATE TABLE providers (id INT GENERATED BY DEFAULT AS IDENTITY NOT NULL, code VARCHAR(64) NOT NULL, name VARCHAR(255) NOT NULL, off_peak_start VARCHAR(8) DEFAULT NULL, off_peak_end VARCHAR(8) DEFAULT NULL, off_peak_multiplier NUMERIC(20, 6) DEFAULT NULL, PRIMARY KEY (id));
CREATE UNIQUE INDEX UNIQ_E225D41777153098 ON providers (code);
